        var sb = new StringBuilder();
        try {
            sb.append("t");
            if (n > 0)
                throw new ArithmeticException();
            return sb.append("r").toString();
        } catch (ArithmeticException e) {
            sb.append("c");
            throw new IllegalStateException(
                sb.toString());
        } finally {
            sb.append("f");
            if (n > 1) return sb.toString();
        }
    }
