public class Main {
    static int score(Object o) {
        return switch (o) {
            case Integer i when i > 10 -> i;
            case Integer i -> {
                int t = 0;
                switch (i) {
                    case 1: t += 1;
                    case 2: t += 2; break;
                    default: t += 5;
                }
                yield t;
            }
            case String s -> s.length();
            default -> -1;
        };
    }
    public static void main(String[] args) {
        System.out.println(score(1) + ","
            + score(12) + "," + score("hey")
            + "," + score(2.0));
    }
}

class Engine { int hp = 100; }
class Car implements Serializable {
    String model = "A";
    transient Engine e1 = new Engine();
    Engine e2;
}
public class Main {
    static Car copy(Car c) throws Exception {
        var bos = new ByteArrayOutputStream();
        try (var out =
                new ObjectOutputStream(bos)) {
            out.writeObject(c);
        }
        try (var in = new ObjectInputStream(
                new ByteArrayInputStream(
                    bos.toByteArray()))) {
            return (Car) in.readObject();
        }
    }
    public static void main(String[] args)
            throws Exception {
        var c = new Car();
        c.model = "B";
        var d = copy(c);
        System.out.print(d.model + " " + d.e1
            + " " + d.e2 + " ");
        c.e2 = new Engine();
        copy(c);
        System.out.print("done");
    }
}

